function patternAlphabetFloydsTriangle(n) {
  let rows = [];
  let code = 65;
  for (let i = 1; i <= n; i++) {
    let row = '';
    for (let j = 1; j <= i; j++) {
      row += String.fromCharCode(code++) + (j === i ? '' : ' ');
    }
    rows.push(row);
  }
  return rows.join('\n');
}

