function patternAlphabetFloydsTriangle(n) {
  let rows = [];
  let code = 65;
  for (let i = 1; i <= n; i++) {
    let row = [];
    for (let j = 1; j <= i; j++) {
      row.push(String.fromCharCode(code++));
    }
    rows.push(row.join(' '));
  }
  return rows.join('\n');
}
